+	se, ok := err.(domain.SourceError)
+	if !ok {
+		t.Fatalf("expected SourceError, got %T: %v", err, err)
+	}
+	if se.Code != domain.ErrParserInvalidYAML {
+		t.Errorf("expected ErrParserInvalidYAML, got %s", se.Code)
+	}
+}
